def is_balanced(text):
    """
    Check if the given string contains only balanced parentheses [], {} and {}.
    Other characters are ignored.
    """
    stack = []
    for ch in text:
        if ch in '[]{}':
            stack.append(ch)
        elif ch == '(':
            if not stack:
                return False
            stack.pop()
        elif ch == ')':
            if not stack:
                return False
            stack.pop()
        elif ch == '{':
            if not stack:
                return False
            stack.pop()
        elif ch == '}':
            if not stack:
                return False
            stack.pop()
        else:
            # Ignore other characters
            pass
    return len(stack) == 0
