def run_length_decode(s):
    result = []
    i = 0
    while i < len(s):
        if s[i] == 'a':
            count = 0
            while i < len(s) and s[i] == 'a':
                count += 1
                i += 1
            result.append(count)
        else:
            result.append(s[i])
            i += 1
    return ''.join(result)
